/* Unit checks (Daily Teaching System, Part 7): two short paper checks per unit, built from the unit's own worksheets.
 *
 *   content/assessments/checks.<loc>.json   GENERATED by scripts/assessments/assemble.js
 *   content/assessments/ui.<loc>.json       the strings of the section and of the printed pages
 *
 * The student forms are printables like any worksheet (GET /api/quota/dl?kind=form, counted as a download); the
 * answer keys and the teacher pages are Teacher-only files (kind=teacher). A check is shown on its unit's page when
 * its status is live. */
export interface CheckPart { part: number; lesson: number; title: string; type: string; tasks: number }
export interface UnitCheck {
  unit: string;
  slug: string;
  status: 'pilot' | 'live';
  parts: CheckPart[];
  notCovered: number[];
  forms: { A: { pages: number }; B: { pages: number } };
}
export type AssessmentUi = Record<string, string>;

const cache = new Map<string, unknown>();
async function load<T>(key: string, importer: () => Promise<{ default: unknown }>): Promise<T | null> {
  if (cache.has(key)) return cache.get(key) as T | null;
  try { const mod = await importer(); cache.set(key, mod.default); } catch { cache.set(key, null); }
  return cache.get(key) as T | null;
}

export const getAssessmentUi = (locale: string) => load<AssessmentUi>(`ui.${locale}`, () => import(`@/content/assessments/ui.${locale}.json`));

/** the check of a unit that the page may show: a live one, or none */
export async function getUnitCheck(locale: string, unitId: string): Promise<UnitCheck | null> {
  const f = await load<{ checks: UnitCheck[] }>(`checks.${locale}`, () => import(`@/content/assessments/checks.${locale}.json`));
  const c = f?.checks.find((x) => x.unit === unitId);
  return c && c.status === 'live' ? c : null;
}

/** a student form: a printable, counted like any download */
export const checkFormHref = (locale: string, unitId: string, form: 'a' | 'b') => `/api/quota/dl?kind=form&loc=${locale}&file=${encodeURIComponent(`checks/${unitId}/check-${form}`)}`;
